    /// <summary>
    /// MPJ_12065_RestrictCostchangesOnPOs on 01 Feb 2022 by chaminda
    /// </summary>
    /// <param name="sender"> Get form control</param>
    /// <param name="e"> Get form data source args </param>
    [FormControlEventHandler(formControlStr(VendParameters, METMetcash_METEnablePOCostUpdateRestrictions), FormControlEventType::Modified),
     SuppressBPWarningAttribute("BPParameterNotUsed", "@MET:BPParameterNotUsedMessage")
    ]
    public static void METMetcash_METEnablePOCostUpdateRestrictions_OnModified(FormControl sender, FormControlEventArgs e)
    {
        FormRun elements         = sender.formRun();
        METVendParametersFormEventHandler::controlElements(elements);      
    }

    /// <summary>
    /// MPJ_12065_RestrictCostchangesOnPOs on 02 Feb 2022 by chaminda
    /// </summary>
    /// <param name="sender"> Get form run object</param>
    /// <param name="e"> Get form data source args</param>
    [FormEventHandler(formStr(VendParameters), FormEventType::PostRun),
     SuppressBPWarningAttribute("BPParameterNotUsed", "@MET:BPParameterNotUsedMessage")
    ]
    public static void VendParameters_OnPostRun(xFormRun sender, FormEventArgs e)
    {
        FormRun elements = sender as FormRun;
        METVendParametersFormEventHandler::controlElements(elements);
    }


    /// <summary>
    /// MPJ_12065_RestrictCostchangesOnPOs on 01 Feb 2022 by chaminda
    /// </summary>
    /// <param name="_element"> Get form run object </param>
    private static void controlElements(FormRun _element)
    {        
        SysGlobalObjectCache    cache = new SysGlobalObjectCache();
        GlobalObjectCacheScope  cacheScope=METConstants::PoRestrictionCache;             
        cache.clear(cacheScope);        
        
        FormControl restriction = _element.design().controlName(formControlStr(VendParameters, METMetcash_METEnablePOCostUpdateRestrictions));
        FormControl percent     = _element.design().controlName(formControlStr(VendParameters, METMetcash_METPOCostChangePercentAllowed));
                
        if(restriction.valuestr() == enum2Str(NoYes::Yes))            
        {
            percent.enabled(true);
        }
        else
        {
            percent.enabled(false);
        }
    }

