    /// <summary>
    /// MPJ_21178_VendorGlobal on 17 Mar 2022 by chaminda
    /// Creating record in METVendParameter table if it doesn't exist.
    /// </summary>
    /// <param name="sender"> Get form data source object</param>
    /// <param name="e"> Get form data source event  args </param>
    [FormEventHandler(formStr(VendParameters), FormEventType::Initialized),
     SuppressBPWarningAttribute("BPParameterNotUsed", "@MET:BPParameterNotUsedMessage")]
    public static void VendParameters_OnInitialized(xFormRun sender, FormEventArgs e)
    {
        METVendParameters metVendParameters;
        metVendParameters= METVendParameters::find();
    }

    /// <summary>
    /// Update or fetch the charge through invoice values based on modification  
    /// </summary>
    /// <param name="sender">FormControl instance</param>
    /// <param name="e">FormControlEventArgs instance</param>
    [FormControlEventHandler(formControlStr(VendParameters, METChargeThroughType), FormControlEventType::Modified)]
    public static void METChargeThroughType_OnModified(FormControl sender, FormControlEventArgs e)
    {
        FormRun formRun = sender.formRun();
        FormStringControl metChargeThroughType = sender as FormStringControl;
        FormDataSource metVendParameters_ds = formRun.dataSource(FormDataSourcestr(VendParameters, metVendParameters));
        METVendParameters metVendParameters = metVendParameters_ds.cursor();

        if (metChargeThroughType.text())
        {
            metVendParameters.ChargeThroughInvoiceType = sender.valueStr();
        }
        else
        {
            metChargeThroughType.text(metVendParameters.ChargeThroughInvoiceType);
        }
       
    }

    /// <summary>
    /// Parameter to check for duplicate on saving CT Header 
    /// </summary>
    /// <param name="sender">VendParameter</param>
    /// <param name="e">FormControlEventArgs</param>
    [FormControlEventHandler(formControlStr(VendParameters, METVendDuplicateCheckOnSavingCTHeader), FormControlEventType::Modified),
     SuppressBPWarningAttribute("BPParameterNotUsed", "@MET:BPParameterNotUsedMessage")]
    public static void METVendDuplicateCheckOnSavingCTHeader_OnModified(FormControl sender, FormControlEventArgs e)
    {
        FormRun formRun = sender.formRun();
        FormStringControl vendDuplicateCheckOnSavingCTHeader = sender as FormStringControl;
        FormDataSource vendParameters_ds = formRun.dataSource(FormDataSourcestr(VendParameters, VendParameters));
        VendParameters vendParameters = vendParameters_ds.cursor();

        if (vendParameters)
        {
            vendParameters.METDuplicateCheckOnSavingCTHeader = sender.valueStr();
            vendDuplicateCheckOnSavingCTHeader.text(vendParameters.METDuplicateCheckOnSavingCTHeader);
        }       
    }
